Arguments: {"code":"const tabId = 2017691689;\n\nasync function getPageJobs() {\n  return await browserjs(tabId, () => {\n    // In Shazamme, let's see how each job card is structured\n    const cards = Array.from(document.querySelectorAll('[data-rel=\"job-card\"], .shm-job-card, [class*=\"job-results-item\"], .dmRespRow[data-rel]'));\n    // If not found, look for titles\n    const links = Array.from(document.querySelectorAll('a[href*=\"/job-details/\"]'));\n    return links.map(a => {\n      // Find containing block\n      let p = a.parentElement;\n      for (let i = 0; i < 5 && p; i++) {\n        if (p.innerText.includes('APPLY NOW') || p.innerText.includes('Posted')) break;\n        p = p.parentElement;\n      }\n      return {\n        title: a.innerText.trim(),\n        href: a.href,\n        snippet: p ? p.innerText.replace(/\\n+/g, ' | ') : ''\n      };\n    }).filter(j => j.title.length > 0 && j.title !== 'READ MORE');\n  });\n}\n\nconst allJobs = [];\nfor (let page = 0; page < 6; page++) {\n  console.log(`Getting page ${page + 1}...`);\n  if (page > 0) {\n    await browserjs(tabId, (pageNum) => {\n      const btn = document.querySelector(`.section-job-results-paging a[data-page-number=\"${pageNum}\"]`);\n      if (btn) btn.click();\n    }, page);\n    await new Promise(r => setTimeout(r, 1500));\n  }\n  const jobs = await getPageJobs();\n  for (const j of jobs) {\n    if (!allJobs.some(x => x.href === j.href)) {\n      allJobs.push(j);\n    }\n  }\n}\n\nconsole.log(`Total Legal People jobs scraped: ${allJobs.length}`);\nconsole.log(JSON.stringify(allJobs.slice(0, 10), null, 2));\nawait write(\"tmp://legal_people_jobs.json\", JSON.stringify(allJobs, null, 2));\n","cwd":null,"title":"Scrape all job listings on Legal People"}
